using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "LacertianBeamCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Hevelius/LacertianBeamCustomDescription", order = 0)]
public class LacertianBeamCustomDescription : WhereXTimesCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		LacertianBeamAction lacertianBeamAction = battleAction as LacertianBeamAction;
		return Smart.Format(GetActionDescription(amountModified, battleAction, lacertianBeamAction.PurifyAction), amountModified, lacertianBeamAction.AdditionalTimesAmount);
	}
}
